args.sparql:
SELECT ?film ?filmLabel ?director ?directorLabel ?birthDate WHERE {
  VALUES ?film { dbr:Fame_(1936_film) dbr:It's_All_About_Love }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:birthDate ?birthDate }
  OPTIONAL { ?director dbp:birthDate ?birthDateLiteral . FILTER(!BOUND(?birthDate)) }
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER(lang(?directorLabel) = 'en') }
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER(lang(?filmLabel) = 'en') }
  # If dbo:birthDate not present, try dbp:birthDate (literal)
  BIND(COALESCE(?birthDate, ?birthDateLiteral) AS ?birthDate)
}
ORDER BY ?filmLabel

